import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

// Load credentials generated by seed script
const users = new SharedArray('users', function () {
    return JSON.parse(open('./loadtest_users.json'));
});

export const options = {
    stages: [
        { duration: '30s', target: 20 }, // Ramp-up: Tăng lên 20 users
        { duration: '1m', target: 50 },  // Steady: Đẩy lên 50 users đồng thời nộp bài
        { duration: '30s', target: 0 },  // Ramp-down: Giảm về 0
    ],
    thresholds: {
        http_req_duration: ['p(95)<1500'], // p95 dưới 1500ms
        http_req_failed: ['rate<0.01'],   // Tỷ lệ lỗi dưới 1%
    },
};

export default function () {
    const BASE_URL = __ENV.BASE_URL || 'http://localhost:3000';
    
    // Pick user based on VU ID
    const userIndex = (__VU - 1) % users.length;
    const user = users[userIndex];
    
    // 1. Lấy CSRF token
    const csrfRes = http.get(`${BASE_URL}/api/auth/csrf`);
    const csrfToken = csrfRes.json().csrfToken;
    
    // 2. Đăng nhập
    const loginPayload = {
        email: user.email,
        password: user.password,
        csrfToken: csrfToken,
        callbackUrl: '/',
        json: 'true'
    };
    const loginRes = http.post(`${BASE_URL}/api/auth/callback/credentials`, loginPayload);
    const isLoginOk = check(loginRes, {
        'login successful': (r) => r.status === 200,
    });
    
    if (isLoginOk) {
        // 3. Khởi tạo bài trắc nghiệm (mbti)
        const initHeaders = { 'Content-Type': 'application/json' };
        const initPayload = JSON.stringify({
            student_id: user.id,
            test_type: 'mbti'
        });
        
        const initRes = http.post(`${BASE_URL}/api/tests`, initPayload, { headers: initHeaders });
        
        const isInitOk = check(initRes, {
            'test initialized (200)': (r) => r.status === 200,
            'has test_id': (r) => r.json().test_id !== undefined,
        });
        
        if (isInitOk) {
            const testId = initRes.json().test_id;
            
            // 4. Nộp tiến độ bài test (save_progress_only = true để tránh gọi AI thật và test ghi DB nhanh)
            const submitHeaders = { 'Content-Type': 'application/json' };
            const submitPayload = JSON.stringify({
                test_id: testId,
                student_id: user.id,
                test_type: 'mbti',
                answers: {
                    "1": "A", "2": "A", "3": "B", "4": "B", "5": "A",
                    "6": "B", "7": "A", "8": "A", "9": "B", "10": "B"
                },
                save_progress_only: true
            });
            
            const submitRes = http.post(`${BASE_URL}/api/tests/submit`, submitPayload, { headers: submitHeaders });
            check(submitRes, {
                'submit success (200)': (r) => r.status === 200 && r.json().success === true,
            });
        }
    }
    
    sleep(2);
}
